	const struct net *net;
	char val[MPTCP_SCHED_NAME_MAX];
	struct ctl_table tbl = {
		.data = val,
		.maxlen = MPTCP_SCHED_NAME_MAX,
	};
	int ret;

	if (!current->nsproxy)
		return -EINVAL;

	net = current->nsproxy->net_ns;
	strscpy(val, mptcp_get_scheduler(net), MPTCP_SCHED_NAME_MAX);

